import fs from 'node:fs';
import path from 'node:path';
import { AiE2eError } from './errors.js';
import { git, tryGit } from './git.js';
export const BLOCK_START = '# >>> ai-e2e >>>';
export const BLOCK_END = '# <<< ai-e2e <<<';
const CREATED_MARKER = '# ai-e2e: file created by `ai-e2e init`; `ai-e2e uninstall` removes it.';
const SHELL_SHEBANG = /^#!\s*(?:\/usr\/bin\/env\s+)?(?:\/(?:usr\/)?(?:local\/)?bin\/)?(?:sh|bash|zsh|dash|ksh)\b/;
export function shellQuote(value) {
    if (/[\0\r\n]/.test(value))
        throw new AiE2eError('Path contains characters that cannot be embedded in a hook.');
    return `'${value.replace(/'/g, `'\\''`)}'`;
}
export function cliReference(root, cliPath) {
    const rel = path.relative(root, cliPath);
    if (!rel.startsWith('..') && !path.isAbsolute(rel))
        return `"$ai_e2e_root"/${shellQuote(rel.split(path.sep).join('/'))}`;
    return shellQuote(cliPath);
}
export function hookBlock(cliRef) {
    return [
        BLOCK_START,
        '# Optional AI E2E test generation. Never blocks the push. Set AI_E2E_SKIP=1 to bypass.',
        'if [ -z "${AI_E2E_SKIP:-}" ] && command -v node >/dev/null 2>&1; then',
        '  ai_e2e_root="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"',
        '  ai_e2e_cli="$(command -v ai-e2e 2>/dev/null || true)"',
        `  [ -n "$ai_e2e_cli" ] || ai_e2e_cli=${cliRef}`,
        '  if [ -f "$ai_e2e_cli" ] && ai_e2e_refs="$(mktemp "${TMPDIR:-/tmp}/ai-e2e-refs.XXXXXX" 2>/dev/null)"; then',
        '    cat > "$ai_e2e_refs" || true',
        '    node "$ai_e2e_cli" hook pre-push "$@" < "$ai_e2e_refs" || true',
        '    exec 0< "$ai_e2e_refs"',
        '    rm -f "$ai_e2e_refs" 2>/dev/null || true',
        '  elif [ ! -f "$ai_e2e_cli" ]; then',
        '    echo "ai-e2e: CLI not found at $ai_e2e_cli (run the ai-e2e build); skipping." >&2',
        '  fi',
        '  unset ai_e2e_root ai_e2e_cli ai_e2e_refs',
        'fi',
        BLOCK_END,
    ].join('\n');
}
function readJson(file) {
    try {
        return JSON.parse(fs.readFileSync(file, 'utf8'));
    }
    catch {
        return null;
    }
}
function readIfExists(file) {
    try {
        return fs.readFileSync(file, 'utf8');
    }
    catch (error) {
        if (error.code === 'ENOENT')
            return null;
        throw error;
    }
}
export async function resolveHookTarget(root) {
    const hooksPath = (await tryGit(root, ['config', '--get', 'core.hooksPath']))?.trim() ?? '';
    let file;
    let manager = 'git';
    if (/(^|[\\/])\.husky([\\/]_)?[\\/]?$/.test(hooksPath)) {
        file = path.join(root, '.husky', 'pre-push');
        manager = 'husky';
    }
    else {
        const hooksDir = (await git(root, ['rev-parse', '--git-path', 'hooks'])).trim();
        file = path.join(path.resolve(root, hooksDir), 'pre-push');
    }
    let blockedBy = null;
    const pkg = readJson(path.join(root, 'package.json'));
    const huskyV4 = pkg?.husky;
    if (typeof huskyV4 === 'object' && huskyV4 !== null && 'hooks' in huskyV4)
        blockedBy = 'husky v4 (hooks declared in package.json)';
    else if (pkg && 'simple-git-hooks' in pkg)
        blockedBy = 'simple-git-hooks (regenerates hook files)';
    const existing = readIfExists(file);
    if (existing && !existing.includes(BLOCK_START)) {
        if (/lefthook/i.test(existing))
            blockedBy = 'lefthook (regenerates hook files)';
        else if (/generated by pre-commit/i.test(existing))
            blockedBy = 'pre-commit framework (regenerates hook files)';
        else if (existing.startsWith('#!') && !SHELL_SHEBANG.test(existing))
            blockedBy = 'existing pre-push hook is not a POSIX shell script';
    }
    return { file, manager, blockedBy };
}
function insertBlock(content, block) {
    const lines = content.split('\n');
    let index = 0;
    if (lines[0]?.startsWith('#!'))
        index = 1;
    while (index < lines.length && /husky\.sh|^\s*\.\s+"?\$\(dirname/.test(lines[index]))
        index++;
    lines.splice(index, 0, ...block.split('\n'));
    return lines.join('\n');
}
function removeBlock(content) {
    return replaceBlock(content, null);
}
function replaceBlock(content, block) {
    const lines = content.split('\n');
    const start = lines.indexOf(BLOCK_START);
    const end = lines.indexOf(BLOCK_END, start);
    if (start === -1 || end === -1)
        return content;
    lines.splice(start, end - start + 1, ...(block === null ? [] : block.split('\n')));
    return lines.join('\n');
}
async function isTracked(root, file) {
    const rel = path.relative(root, file);
    if (rel.startsWith('..'))
        return false;
    return (await tryGit(root, ['ls-files', '--error-unmatch', '--', rel])) !== null;
}
export async function installHook(root, cliPath, backupDir, force = false) {
    const target = await resolveHookTarget(root);
    const base = { file: target.file, manager: target.manager, tracked: await isTracked(root, target.file) };
    if (target.blockedBy && !force)
        return { ...base, action: 'blocked', reason: target.blockedBy };
    const block = hookBlock(cliReference(root, cliPath));
    const existing = readIfExists(target.file);
    let next;
    let action;
    if (existing === null) {
        next = target.manager === 'husky' ? `${block}\n` : `#!/bin/sh\n${CREATED_MARKER}\n${block}\nexit 0\n`;
        action = 'created';
    }
    else if (existing.includes(BLOCK_START)) {
        next = replaceBlock(existing, block);
        action = next === existing ? 'unchanged' : 'updated';
    }
    else {
        next = insertBlock(existing, block);
        action = 'inserted';
    }
    if (action === 'unchanged')
        return { ...base, action };
    let backup;
    if (existing !== null) {
        fs.mkdirSync(backupDir, { recursive: true });
        backup = path.join(backupDir, `pre-push.${new Date().toISOString().replace(/[:.]/g, '-')}`);
        fs.writeFileSync(backup, existing);
    }
    fs.mkdirSync(path.dirname(target.file), { recursive: true });
    fs.writeFileSync(target.file, next);
    if (existing === null)
        fs.chmodSync(target.file, 0o755);
    return { ...base, action, ...(backup ? { backup } : {}) };
}
export async function uninstallHook(root) {
    const target = await resolveHookTarget(root);
    const existing = readIfExists(target.file);
    if (existing === null || !existing.includes(BLOCK_START))
        return { action: 'not-installed', file: target.file };
    const remaining = removeBlock(existing);
    const createdByUs = remaining.includes(CREATED_MARKER);
    const stripped = remaining.replace(`${CREATED_MARKER}\n`, '');
    if ((createdByUs && /^#!\/bin\/sh\n(exit 0\n)?$/.test(stripped)) || stripped.trim() === '') {
        fs.rmSync(target.file);
        return { action: 'deleted-file', file: target.file };
    }
    fs.writeFileSync(target.file, stripped);
    return { action: 'removed-block', file: target.file };
}
/** Appends the state directory to .gitignore unless Git already ignores it. */
export async function ensureGitignored(root, stateDir) {
    const rel = path.relative(root, stateDir).split(path.sep).join('/');
    if (!rel || rel.startsWith('..') || path.isAbsolute(rel))
        return 'outside-repo';
    if ((await tryGit(root, ['check-ignore', '-q', '--no-index', `${rel}/job.json`])) !== null)
        return 'already-ignored';
    const file = path.join(root, '.gitignore');
    const current = readIfExists(file) ?? '';
    const prefix = current === '' || current.endsWith('\n') ? '' : '\n';
    fs.appendFileSync(file, `${prefix}# ai-e2e runtime state (jobs, logs)\n/${rel}/\n`);
    return 'added';
}
